func NewCfg() *Cfg {
	return &Cfg{
		Target: []string{"all"},
		Logger: log.New("settings"),
		Raw:    ini.Empty(),
		Azure:  &azsettings.AzureSettings{},

		// Avoid nil pointer
		IsFeatureToggleEnabled: func(_ string) bool {
			return false
		},
	}
}

